import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// RequireAdmin must make the admin's *store.User available through UserFrom,
// the same as Require does; handlers such as audit dereference it.
func TestRequireAdminUserFrom(t *testing.T) {
	s := newStore(t)
	var got *store.User
	h := RequireAdmin(s, http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		got = UserFrom(r.Context())
	}))
	req := httptest.NewRequestWithContext(t.Context(), http.MethodDelete, "/", nil)
	req.Header.Set("Authorization", "Bearer tok-admin")
	h.ServeHTTP(httptest.NewRecorder(), req)
	if got == nil {
		t.Fatal("UserFrom returned nil for an authenticated admin")
	}
	if got.ID != "root" {
		t.Errorf("user %q, want root", got.ID)
	}
}
"}

